<script>
(() => {
  "use strict";

  const hero = document.getElementById("coin-hero");
  const ctx = hero.getContext("2d", { alpha:false });
  const TAU = Math.PI * 2;
  let running = true;
  let raf = 0;
  let start = performance.now();
  let lastT = 0;

  function clamp(v,a,b){ return Math.max(a,Math.min(b,v)); }
  function norm(v){
    const l=Math.hypot(v.x,v.y,v.z)||1;
    return {x:v.x/l,y:v.y/l,z:v.z/l};
  }
  const light = norm({x:-.56,y:-.48,z:.95});
  const halfLight = norm({x:light.x,y:light.y,z:light.z+1});

  function makeFace(front){
    const s=768, c=document.createElement("canvas");
    c.width=c.height=s;
    const g=c.getContext("2d");
    const cx=s/2, cy=s/2, r=s*.488;

    g.save();
    g.beginPath(); g.arc(cx,cy,r,0,TAU); g.clip();

    let base=g.createRadialGradient(s*.33,s*.26,s*.015,s*.5,s*.5,s*.7);
    if(front){
      base.addColorStop(0,"#fff1a6");
      base.addColorStop(.16,"#d99b3f");
      base.addColorStop(.48,"#855021");
      base.addColorStop(.72,"#c78332");
      base.addColorStop(1,"#4d2b14");
    }else{
      base.addColorStop(0,"#f1ce78");
      base.addColorStop(.2,"#9f672b");
      base.addColorStop(.53,"#4d2c16");
      base.addColorStop(.78,"#b47832");
      base.addColorStop(1,"#3c2111");
    }
    g.fillStyle=base; g.fillRect(0,0,s,s);

    // Deterministic fine metal grain.
    for(let i=0;i<420;i++){
      const a=i*2.399963, rr=Math.sqrt((i+.5)/420)*r;
      const x=cx+Math.cos(a)*rr, y=cy+Math.sin(a)*rr;
      const alpha=.018+.018*(.5+.5*Math.sin(i*7.17));
      g.fillStyle=i%3 ? `rgba(255,235,176,${alpha})` : `rgba(50,25,8,${alpha})`;
      g.beginPath();g.arc(x,y,.7+(i%4)*.3,0,TAU);g.fill();
    }
    for(let i=0;i<54;i++){
      const y=(i+.5)*s/54;
      g.strokeStyle=`rgba(255,245,205,${.009+.006*Math.sin(i)})`;
      g.beginPath();g.moveTo(0,y);g.lineTo(s,y+Math.sin(i*2)*2);g.stroke();
    }

    function reliefCircle(radius,width){
      g.lineWidth=width;
      g.strokeStyle="rgba(47,22,7,.78)";
      g.beginPath();g.arc(cx+2.5,cy+3,radius,0,TAU);g.stroke();
      g.strokeStyle="rgba(255,225,142,.62)";
      g.beginPath();g.arc(cx-2,cy-2,radius,0,TAU);g.stroke();
      g.strokeStyle="rgba(121,73,26,.9)";
      g.lineWidth=Math.max(2,width*.32);
      g.beginPath();g.arc(cx,cy,radius,0,TAU);g.stroke();
    }
    reliefCircle(r*.91,15);
    reliefCircle(r*.78,7);
    reliefCircle(r*.59,5);

    function embossedText(text,x,y,size,font,align="center"){
      g.textAlign=align;g.textBaseline="middle";
      g.font=`900 ${size}px ${font}`;
      g.fillStyle="rgba(45,21,7,.86)";g.fillText(text,x+4,y+5);
      g.fillStyle="rgba(255,222,137,.62)";g.fillText(text,x-2,y-2);
      g.fillStyle=front?"#966026":"#74451f";g.fillText(text,x,y);
      g.strokeStyle="rgba(56,28,9,.72)";g.lineWidth=Math.max(1.5,size*.026);g.strokeText(text,x,y);
    }

    if(front){
      embossedText("WASTEDTOKEN",cx,cy-r*.66,43,"Arial");
      embossedText("MINT",cx,cy+r*.67,39,"Arial");
      embossedText("WT",cx,cy-4,190,"Georgia");
      g.lineJoin="round";
      g.lineWidth=15;
      g.strokeStyle="rgba(52,26,8,.78)";
      g.beginPath();
      g.moveTo(cx-r*.32,cy+r*.29);g.lineTo(cx,cy+r*.42);g.lineTo(cx+r*.32,cy+r*.29);
      g.stroke();
      g.lineWidth=6;g.strokeStyle="rgba(255,218,126,.58)";g.stroke();
      embossedText("EST.  MMXXIV",cx,cy+r*.49,23,"Arial");
      for(let k=-1;k<=1;k+=2){
        g.fillStyle="#70431c";
        g.beginPath();g.arc(cx+k*r*.64,cy,13,0,TAU);g.fill();
        g.strokeStyle="rgba(255,227,150,.58)";g.lineWidth=3;g.stroke();
      }
    }else{
      embossedText("10,000",cx,cy-52,115,"Georgia");
      embossedText("TOKENS",cx,cy+70,58,"Arial");
      embossedText("PROOF OF PARTICIPATION",cx,cy-r*.65,30,"Arial");
      embossedText("NON-TRANSFERABLE GLORY",cx,cy+r*.66,27,"Arial");
      embossedText("№ 042",cx,cy+r*.40,29,"Georgia");
      for(let i=0;i<12;i++){
        const a=i*TAU/12-Math.PI/2, rr=r*.65;
        g.save();g.translate(cx+Math.cos(a)*rr,cy+Math.sin(a)*rr);g.rotate(a+Math.PI/2);
        g.fillStyle=i%2?"#5c3417":"#c28a3c";
        g.beginPath();
        for(let j=0;j<10;j++){
          const q=j*Math.PI/5-Math.PI/2, rad=j%2?5:11;
          g.lineTo(Math.cos(q)*rad,Math.sin(q)*rad);
        }
        g.closePath();g.fill();g.restore();
      }
    }

    g.restore();
    g.lineWidth=7;g.strokeStyle="rgba(255,226,145,.72)";
    g.beginPath();g.arc(cx,cy,r-4,0,TAU);g.stroke();
    g.lineWidth=4;g.strokeStyle="rgba(38,18,7,.9)";
    g.beginPath();g.arc(cx,cy,r-10,0,TAU);g.stroke();
    return c;
  }

  const frontTexture=makeFace(true);
  const backTexture=makeFace(false);

  function resizeHero(){
    const rect=hero.getBoundingClientRect();
    const dpr=Math.min(2,window.devicePixelRatio||1);
    const w=Math.max(1,Math.round(rect.width*dpr));
    const h=Math.max(1,Math.round(rect.height*dpr));
    if(hero.width!==w||hero.height!==h){ hero.width=w;hero.height=h; }
    render(lastT);
  }

  function render(t){
    t=((Number(t)||0)%1+1)%1;
    lastT=t;
    const w=hero.width,h=hero.height;
    ctx.setTransform(1,0,0,1,0,0);
    ctx.clearRect(0,0,w,h);

    const bg=ctx.createRadialGradient(w*.5,h*.43,0,w*.5,h*.5,Math.max(w,h)*.67);
    bg.addColorStop(0,"#1b1715");
    bg.addColorStop(.42,"#101014");
    bg.addColorStop(1,"#070709");
    ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);

    const floor=ctx.createRadialGradient(w*.5,h*.81,0,w*.5,h*.81,w*.31);
    floor.addColorStop(0,"rgba(190,120,48,.105)");
    floor.addColorStop(1,"rgba(0,0,0,0)");
    ctx.fillStyle=floor;ctx.fillRect(0,0,w,h);

    const ay=TAU*t;
    const ax=TAU*2*t;
    const ca=Math.cos(ay), sa=Math.sin(ay);
    const cxr=Math.cos(ax), sxr=Math.sin(ax);

    const U={x:ca, y:sxr*sa, z:-cxr*sa};
    const V={x:0,  y:cxr,    z:sxr};
    const N={x:sa, y:-sxr*ca,z:cxr*ca};

    const R=Math.min(w*.275,h*.405);
    const thick=R*.19;
    const center={x:w*.5,y:h*.48};

    // Soft ground shadow responds to the projected coin width.
    const projectedWidth=R*(.32+Math.sqrt(U.x*U.x+V.x*V.x)*.68);
    ctx.save();
    ctx.translate(center.x,center.y+R*1.17);
    ctx.scale(Math.max(.45,projectedWidth/R),.19);
    const sh=ctx.createRadialGradient(0,0,0,0,0,R*1.25);
    sh.addColorStop(0,"rgba(0,0,0,.52)");
    sh.addColorStop(.55,"rgba(0,0,0,.25)");
    sh.addColorStop(1,"rgba(0,0,0,0)");
    ctx.fillStyle=sh;ctx.beginPath();ctx.arc(0,0,R*1.25,0,TAU);ctx.fill();ctx.restore();

    // Repeated side facets form the genuinely reeded edge.
    const facets=[];
    const count=144;
    for(let i=0;i<count;i++){
      const a0=TAU*i/count, a1=TAU*(i+1)/count;
      const am=(a0+a1)*.5;
      const radial={
        x:Math.cos(am)*U.x+Math.sin(am)*V.x,
        y:Math.cos(am)*U.y+Math.sin(am)*V.y,
        z:Math.cos(am)*U.z+Math.sin(am)*V.z
      };
      if(radial.z<=-.02) continue;
      function point(a,s){
        return {
          x:center.x+R*(Math.cos(a)*U.x+Math.sin(a)*V.x)+s*thick*.5*N.x,
          y:center.y+R*(Math.cos(a)*U.y+Math.sin(a)*V.y)+s*thick*.5*N.y
        };
      }
      const p0=point(a0,-1),p1=point(a1,-1),p2=point(a1,1),p3=point(a0,1);
      const diff=Math.max(0,radial.x*light.x+radial.y*light.y+radial.z*light.z);
      const sp=Math.pow(Math.max(0,radial.x*halfLight.x+radial.y*halfLight.y+radial.z*halfLight.z),34);
      facets.push({p0,p1,p2,p3,diff,sp,i,depth:radial.z});
    }
    facets.sort((a,b)=>a.depth-b.depth);
    for(const f of facets){
      const reed=f.i%2===0 ? -18:12;
      const rr=clamp(67+f.diff*91+f.sp*150+reed,32,225);
      const gg=clamp(39+f.diff*65+f.sp*122+reed*.65,21,185);
      const bb=clamp(18+f.diff*30+f.sp*75,10,115);
      ctx.fillStyle=`rgb(${rr|0},${gg|0},${bb|0})`;
      ctx.beginPath();
