      band.addColorStop(0,"rgba(255,247,210,0)");
      band.addColorStop(.34,"rgba(255,233,165,.04)");
      band.addColorStop(.49,"rgba(255,252,225,.42)");
      band.addColorStop(.55,"rgba(255,236,172,.24)");
      band.addColorStop(1,"rgba(255,224,143,0)");
