      glint.addColorStop(0,"rgba(255,253,226,.24)");
      glint.addColorStop(.26,"rgba(255,224,150,.07)");
      glint.addColorStop(1,"rgba(255,255,255,0)");
      ctx.fillStyle=glint;ctx.fillRect(-1.2,-1.2,2.4,2.4);

      const shade=ctx.createRadialGradient(-.2,-.28,.22,0,0,1.13);
      shade.addColorStop(.45,"rgba(0,0,0,0)");
      shade.addColorStop(1,"rgba(30,12,3,.31)");
      ctx.fillStyle=shade;ctx.fillRect(-1.1,-1.1,2.2,2.2);
      ctx.restore();

      // Crisp raised perimeter.
      ctx.save();
      ctx.setTransform(FU.x*R,FU.y*R,V.x*R,V.y*R,faceCenter.x,faceCenter.y);
      ctx.lineWidth=.018;
      ctx.strokeStyle="rgba(255,229,151,.62)";
      ctx.beginPath();ctx.arc(0,0,.985,0,TAU);ctx.stroke();
      ctx.lineWidth=.011;ctx.strokeStyle="rgba(45,20,6,.8)";
      ctx.beginPath();ctx.arc(0,0,.945,0,TAU);ctx.stroke();
      ctx.restore();
    }

    // Narrow traveling glint on the rim.
    const ga=TAU*(t*.9+.59);
    const gx=center.x+Math.cos(ga)*R*.96, gy=center.y+Math.sin(ga)*R*.62;
    const rimGlow=ctx.createRadialGradient(gx,gy,0,gx,gy,R*.18);
    rimGlow.addColorStop(0,"rgba(255,244,198,.24)");
    rimGlow.addColorStop(1,"rgba(255,255,255,0)");
    ctx.fillStyle=rimGlow;ctx.fillRect(gx-R*.2,gy-R*.2,R*.4,R*.4);
  }

